    userResult.fold(
      (failure) => emit(CartState.error(failure: failure)),
      (user) async {
        final result = await _loadCart(LoadCartParams(userId: user.id));
        result.fold(
          (failure) => emit(CartState.error(failure: failure)),
          (cart) => emit(CartState.success(cart: cart)),
        );
      },
    );
  }
}
